export const API_ORIGIN='https://api.gamehubstar.com';
export const TOKEN_KEY='gamehubstar_token', FAVORITES_KEY='playnest-favorites';
export const uniqueIds=a=>[...new Set((Array.isArray(a)?a:[]).filter(x=>typeof x==='string'))];
export function createApi(fetcher=globalThis.fetch){return async(path,{method='GET',body,token,signal}={})=>{
 const controller=new AbortController(),abort=()=>controller.abort();signal?.addEventListener('abort',abort,{once:true});if(signal?.aborted)abort();const timer=setTimeout(abort,15000);
 try{const response=await fetcher(API_ORIGIN+path,{method,headers:{...(body!==undefined?{'Content-Type':'application/json'}:{}),...(token?{Authorization:`Bearer ${token}`}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{}),signal:controller.signal,cache:'no-store'});let data;try{data=await response.json();}catch{throw Error('The service returned an unexpected response. Please try again.');}if(!response.ok||data.error){const e=Error(data.error||'The request could not be completed. Please try again.');e.status=response.status;throw e;}return data;
 }catch(e){if(e.name==='AbortError')throw Error('The request timed out or was cancelled. Please try again.');if(e instanceof TypeError)throw Error('Could not connect. Check your connection and try again.');throw e;}finally{clearTimeout(timer);signal?.removeEventListener('abort',abort);}
};}
export function normalizeRating(r){const likes=Math.max(0,Math.floor(Number(r?.likes)||0)),dislikes=Math.max(0,Math.floor(Number(r?.dislikes)||0));const n=r?.rating;return{likes,dislikes,rating:likes+dislikes>0&&n!=null&&Number.isFinite(Number(n))&&Number(n)>=1&&Number(n)<=5?Number(n):null};}
export function gameSchema(game,value){const r=normalizeRating(value),schema={'@context':'https://schema.org','@type':'VideoGame',name:game.title,description:Array.from(String(game.summary||game.review||'')).slice(0,200).join(''),image:game.thumb,url:`https://gamehubstar.com/game/${encodeURIComponent(game.id)}`,genre:game.category,applicationCategory:'Game',operatingSystem:'Web Browser'};if(r.rating!==null)schema.aggregateRating={'@type':'AggregateRating',ratingValue:r.rating,ratingCount:r.likes+r.dislikes,bestRating:5,worstRating:1};return schema;}
export function mobileStatus(game={},nav=globalThis.navigator){const ua=nav?.userAgent||'',ios=/iPad|iPhone|iPod/.test(ua)||(/Macintosh/.test(ua)&&nav?.maxTouchPoints>1),a=game.iphoneSupport??game.iphone_support,b=game.androidSupport??game.android_support;if(ios)return a;if(/Android/.test(ua))return b;if([a,b].includes('supported'))return'supported';if(a==='not_supported'&&b==='not_supported')return'not_supported';return a||b?'unverified':undefined;}
export function declaredOrientation(g={}){return ['portrait','landscape','both'].includes(g.orientation)?g.orientation:null;}
export function serialQueue(){let chain=Promise.resolve();return task=>{const result=chain.then(task);chain=result.catch(()=>{});return result;};}
